        },
        Message_Guide_Mod_3 = {
          ContentES = "Las Cuñas Demoníacas se dividen en dos tipos: las <H>Cuñas Demoníacas de personaje</> y las <H>Cuñas Demoníacas de arma</>, y no son intercambiables."
        },
        Message_Guide_Mod_4 = {
          ContentES = "Las Cuñas Demoníacas proveen diversos efectos de mejora; deben <H>equiparse en casillas</> para que surtan efecto."
        },
        Message_Guide_Mod_5 = {
