        RESOURCE_DESC_12018 = {
          ContentES = "Componente de Inflorescencia de Embla fabricado con precisión según los planos. Su poderosa fuerza de retroceso lo convierte en un resorte a punto de estallar, listo para dispararse. Basta un leve contacto para liberar de golpe toda la energía acumulada."
        },
        RESOURCE_DESC_12019 = {
