        RESOURCE_DESC_12145 = {
          ContentES = "Fabricado con precisión a partir del plano de Brillo de polluelo. Resistente y robusto, también sirve como un arma contundente eficaz o como proyectil cuando se acaban las balas."
        },
        RESOURCE_DESC_12146 = {
          ContentES = "Fabricado con precisión a partir del plano de Brillo de polluelo. De aquí brotan las balas, mientras el cañón y el corazón del combatiente arden con el mismo fervor incontenible."
