        },
        RESOURCE_DESC_122 = {
          ContentES = "Un pedido de Phoxene a Lunosirvienta. Otorga una entrega diaria durante la suscripción."
        },
        RESOURCE_DESC_123 = {
          ContentES = "Edición prestigio que recopila poemas dispersos."
        },
        RESOURCE_DESC_124 = {
          ContentES = "Edición coleccionista que recopila poemas dispersos."
        },
        RESOURCE_DESC_125 = {
          ContentES = "Permite elegir uno de los Geniemon ofrecidos como Recompensa de Encuadernación. Un testimonio de tu aventura y un símbolo de gratitud."
        },
        RESOURCE_DESC_19000 = {
          ContentES = "Las huellas del alma entrelazadas convergen aquí. Aquí reside la complejidad."
        },
        RESOURCE_DESC_19001 = {
          ContentES = "Las huellas del alma convergen aquí. Aquí reside la alegría."
