        RESOURCE_DESC_41019 = {
          ContentES = "Cuac-cuac. Risas que transforman los rayos de sol en un arcoíris."
        },
        RESOURCE_DESC_41020 = {
          ContentES = "Guarda un rayo de sol y un trozo de playa en tu corazón. Entonces estés donde estés, siempre será verano."
        },
        RESOURCE_DESC_41021 = {
