        RESOURCE_DESC_GENERALSKIN_6 = {
          ContentES = "Permite seleccionar un aspecto de personaje entre Flora, Dama Nifle, Su Yi, Fina, Rebecca, Fushu, Lynn, Hilda, Hellfire, Camilla, Rhythm, Zhiliu y Psyche."
        },
        RESOURCE_DESC_HYPERWEAPONPROTOTYPE = {
          ContentES = "Uno de los prototipos legendarios de Arma de calamidad.\nSu destino fue amargo como el ajenjo, afilado como una espada de dos filos.\nSe obtiene por medios especiales y puede usarse como material de fusión para Armas de calamidad."
        },
        RESOURCE_DESC_LASTROOT = {
          ContentES = "Extraído de las arenas movedizas de la memoria, este pensamiento completo conserva ecos de alguien, de un pasado aún por llegar o de un futuro ya olvidado."
        },
        RESOURCE_DESC_MONSTERITEM_Diguo = {
          ContentES = "Insignia obtenida al derrotar enemigos del Imperio Hiperbóreo. El poder supremo que perseguían murió en la cuna de su derrota.\nPuede usarse para forjar Armas de calamidad."
        },
        RESOURCE_DESC_MONSTERITEM_Dongguo = {
          ContentES = "Insignia obtenida al derrotar enemigos de Huaxu. La paz construida sobre la voluntad humana y la ley es un equilibrio que millones de personas han sostenido durante miles de años.\nPuede usarse para forjar Armas de calamidad."
        },
        RESOURCE_DESC_MONSTERITEM_Huishou = {
          ContentES = "Insignia obtenida al derrotar Filthoids. El recuerdo de la hoja rajando el inmundo caparazón del monstruo sigue grabado en tu mente; ni una gota de sangre brotó de las heridas.\nPuede usarse para forjar Armas de calamidad."
        },
        RESOURCE_DESC_MONSTERITEM_Jiaohui = {
          ContentES = "Insignia obtenida al derrotar enemigos de la Iglesia Elysiana. La fe se quebró en la larga noche, y el asceta maldijo al sol que tardaba en salir.\nPuede usarse para forjar Armas de calamidad."
        },
        RESOURCE_DESC_MONSTERITEM_Tongmeng = {
          ContentES = "Insignia obtenida al derrotar miembros de Los Abandonados. Abandonados por el mundo, y ellos respondieron con matanza. ¿Pero puede la sangre redimirlos?\nPuede usarse para forjar Armas de calamidad."
        },
        RESOURCE_DESC_MUSIC = {
          ContentES = "Una partitura cuyas notas trazan una historia, como huellas dejadas en la arena."
        },
        RESOURCE_DESC_OPTCHAR_1 = {
          ContentES = "Permite elegir una de las siguientes recompensas: Pensamientos: Berenica ×30, Pensamientos: Margie ×30, Pensamientos: Randy ×30, Pensamientos: Outsider ×30, Pensamientos: Daphne ×30, Pensamientos: Dama Nifle ×30, Pensamientos: Rebecca ×30, Pensamientos: Lynn ×30, Pensamientos: Sibylle ×30, Pensamientos: Tabethe ×30, Pensamientos: Lisbell ×30, Pensamientos: Rhythm ×30, Pensamientos: Hellfire ×30, Pensamientos: Truffle y Filbert ×30, Pensamientos: Yale y Oliver ×30, Pensamientos: Phantasio ×30 o Pensamientos: Psyche ×30."
        },
        RESOURCE_DESC_OPTWEAPON_1 = {
          ContentES = "Se usa para elegir un arma de la lista."
        },
        RESOURCE_DESC_OPTWEAPON_2 = {
          ContentES = "Permite elegir una de las siguientes recompensas: Hoja de Ámbar Radiante, Alma Desvanecida, Sed Abrasadora, Mirada de Tiburón Insondable, Látigo de Cadenas, Sombra Marchita, Desgarrador, Excresencia, Destrucción, Chirrido, Desgarralmas, Rompehuesos, Tácticas Geniales, Beso de Sirena, Forjador de Hierro, Colmillos Exiliados, Oneiros Inmortal, Momiji Itteki, Singularidad Entrópica, Pulsación Azulada, Edicto Plateado, Sembrador Silencioso, Llama de Purificación, Suspiro del Desierto, Reminiscencia Remanente, Rosa Errante, Decreto Sacrosanto, Hidra del Trueno Desterrada, Serenata Sumergida, Alabarda de Jade Primaveral, Arrecife Espectral, Trinquete de Guixu, Grillete del Lobo Solitario, Coro Sagrado, Finalidad Estelar, Arte Explosivo, Infierno Punitivo, Día del Veredicto Sagrado, Inflorescencia de Embla, Arco de Luz Apocalíptico, Fervor Sagrado, Antaño Áureo, Himno del Amanecer o Abundancia de la Esperanza."
        },
        RESOURCE_DESC_PHANTOM = {
          ContentES = "Un sello usado para invocar a un aliado, un símbolo de lucha codo a codo, un lazo de confianza para caminar juntos, una promesa silenciosa.\nCuando tus oraciones transmiten tus pensamientos, esa persona aparecerá a tu lado."
        },
        RESOURCE_DESC_ROOT = {
          ContentES = "Fragmentos de pensamiento extraídos de las arenas movedizas de la memoria, contienen recuerdos pasados o futuros sobre cierta persona."
        },
        RESOURCE_DESC_TICKET = {
          ContentES = "Sigue los pasos de la calamidad, busca el poder capaz de derribar el mundo y deja que la brújula marque tu camino.\nPuede usarse para entrar en la Expedición abisal."
