        RLBlessingGroup_Active = {
          ContentES = "Puede ser activado"
        },
        RLBlessingGroup_Desc_1 = {
          ContentES = "Mejoras de armas cuerpo a cuerpo"
        },
        RLBlessingGroup_Desc_101 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Prob. CRIT y + <Highlight>15%</> de Daño CRIT para armas cuerpo a cuerpo.\nInfligir daño con armas cuerpo a cuerpo tiene un <Highlight>10%</> de probabilidad de aplicar 1 acumulación de [Llama fundida]."
        },
        RLBlessingGroup_Desc_102 = {
          ContentES = "[Llama fundida] inflige un <Highlight>35%</> del ATQ del personaje como daño periódico cada <Highlight>1</>s."
        },
        RLBlessingGroup_Desc_103 = {
          ContentES = "Extiende la duración de [Llama fundida] a <Highlight>10</> s. Ahora se acumula hasta <Highlight>20</> veces."
        },
        RLBlessingGroup_Desc_104 = {
          ContentES = "Los objetivos afectados con [Llama fundida] sufren un golpe de [Sable de llama fundida] cada <Highlight>5</> s. Infligir daño con armas cuerpo a cuerpo tiene un <Highlight>10%</> de probabilidad de activar un [Sable de llama fundida] adicional."
        },
        RLBlessingGroup_Desc_2 = {
          ContentES = "Mejoras de armas a distancia"
        },
        RLBlessingGroup_Desc_201 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Prob. CRIT y + <Highlight>15%</> de Daño CRIT para armas a distancia.\nAumenta el Rango de Recogida Automática. Otorga inmunidad al Aturdimiento durante <Highlight>3</> s después de recoger botín."
        },
        RLBlessingGroup_Desc_202 = {
          ContentES = "Infligir daño con cualquier arma a distancia activa [Luna marina] y genera <Highlight>3</> [Mini Lunas marinas] adicionales (máximo una vez cada <Highlight>10</> s)."
        },
        RLBlessingGroup_Desc_203 = {
          ContentES = "Al recolectar una [Mini Luna marina] se obtiene 1 [Luna velada]."
        },
        RLBlessingGroup_Desc_204 = {
          ContentES = "Al consumir [Luna velada] se disparan <Highlight>3</> [Aguijones] en una dispersión en forma de abanico. Recoger botín otorga 1 acumulación de [Deriva fantasma]."
        },
        RLBlessingGroup_Desc_3 = {
          ContentES = "Mejoras de habilidades"
        },
        RLBlessingGroup_Desc_301 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Escudo máximo.\nDaño de Habilidad +<Highlight>25%</>."
        },
        RLBlessingGroup_Desc_302 = {
          ContentES = "Obtiene 1 acumulación de <Highlight>[Destello]</> por segundo (máx. 60). Con 60 acumulaciones, lanzar una habilidad consume todo el <Highlight>[Destello]</> y otorga [Resplandor] durante <Highlight>10 s</>, lo que aumenta el Daño de Habilidad en un <Highlight>50%</>."
        },
        RLBlessingGroup_Desc_303 = {
          ContentES = "Mientras está bajo [Resplandor], activa 1 [Emisión] cada 2 s, lo que inflige Daño de Habilidad equivalente al <Highlight>810%</> del ATQ del personaje a los enemigos dentro de <Highlight>6</> m."
        },
        RLBlessingGroup_Desc_304 = {
          ContentES = "Extiende [Resplandor] a <Highlight>20</> s."
        },
        RLBlessingGroup_Desc_4 = {
          ContentES = "Invocaciones especializadas"
        },
        RLBlessingGroup_Desc_401 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>15%</> de Daño de invocación.\nInvocar una invocación que no sea Lumiramita también invoca 1 [Lumisemilla].\n[Lumisemilla]: Explota cuando un enemigo entra en un radio de <Highlight>3</> m, infligiendo daño equivalente al <Highlight>600%</> del ATQ. Dura <Highlight>10</> s y puede haber hasta 10 simultáneamente."
        },
        RLBlessingGroup_Desc_402 = {
          ContentES = "Cada [Lumisemilla] tiene un <Highlight>40%</> de posibilidades de evolucionar a [Lumihoja] cuando es invocada.\n[Lumihoja]: Explota cuando un enemigo se acerca a <Highlight>3</> m, infligiendo <Highlight>1000%</> del ATQ. Dura <Highlight>10</> s y puede haber hasta 10 simultáneamente."
        },
        RLBlessingGroup_Desc_403 = {
          ContentES = "[Lumihoja] invoca un [Lumiárbol] al explotar. Cuando es sanado, inflige a los enemigos dentro de un radio de 6 m un daño equivalente al <Highlight>4000%</> de los PV restaurados.\n[Lumiárbol]: Cura a los aliados en un radio de <Highlight>10</> m por un <Highlight>5%</> de sus PV Máx. por segundo. Dura <Highlight>10</> s; solo puede existir 1."
        },
        RLBlessingGroup_Desc_404 = {
          ContentES = "Duplica la probabilidad de todos los efectos que pueden invocar [Lumisemilla]. [Lumiárbol] inflige <Highlight>650%</> del ATQ como daño por segundo a los enemigos dentro de su alcance."
        },
        RLBlessingGroup_Desc_5 = {
          ContentES = "Mejoras de movilidad"
        },
        RLBlessingGroup_Desc_501 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>10%</> de Cordura Máx.\nCada acumulación de [Devorador de sombras] aumenta el ATQ del personaje en un <Highlight>1%</>."
        },
        RLBlessingGroup_Desc_502 = {
          ContentES = "Infligir daño otorga <Highlight>5</> acumulaciones de [Devorador de sombras]. Este efecto solo puede activarse una vez cada <Highlight>5</> s."
        },
        RLBlessingGroup_Desc_503 = {
          ContentES = "Restaura <Highlight>2</> de Cordura por segundo por cada 10 acumulaciones de [Devorador de sombras]."
        },
        RLBlessingGroup_Desc_504 = {
          ContentES = "[Polvo de escamas], [Alas de viento] y [Ala de espada] infligen un ataque adicional basado en el ATQ y la Cordura Máx. del personaje (<Highlight>1% × ATQ × Cordura Máx.</>)."
        },
        RLBlessingGroup_Desc_6 = {
          ContentES = "Misiles rastreadores"
        },
        RLBlessingGroup_Desc_601 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>10%</> de Rango de Habilidad.\nAumenta el límite de [Luciérnaga brillante] en <Highlight>+1</>, y ahora sus ataques infligen daño de área en un radio de <Highlight>2</> m."
        },
        RLBlessingGroup_Desc_602 = {
          ContentES = "Obtener [Luciérnaga brillante] tiene un <Highlight>30%</> de probabilidad de generar una variante más grande."
        },
        RLBlessingGroup_Desc_603 = {
          ContentES = "Límite de [Luciérnaga brillante] <Highlight>+1</>. Las variantes más grandes se dividen en <Highlight>3</> [Luciérnagas brillantes] estándar al golpear."
        },
        RLBlessingGroup_Desc_604 = {
          ContentES = "Cuando [Luciérnaga brillante] inflige daño, inflige 1 acumulación que aumenta permanentemente el Daño Recibido en un <Highlight>12%</> en el objetivo, hasta <Highlight>5</> acumulaciones."
        },
        RLBlessingGroup_Desc_7 = {
          ContentES = "Mejora la capacidad de supervivencia y otorga estado de rabia."
        },
        RLBlessingGroup_Desc_701 = {
          ContentES = "Cada Mecha de este conjunto otorga + <Highlight>10%</> de Duración de Habilidad.\nDerrotar a un enemigo aumenta los PV Máx. en <Highlight>0.5%</> (Máx. <Highlight>50%</>)."
        },
        RLBlessingGroup_Desc_702 = {
          ContentES = "Restaura <Highlight>1%</> de PV Máx. por segundo. Efecto aumentado en un <Highlight>0.33%</> por cada <Highlight>25%</> de PV perdido."
        },
        RLBlessingGroup_Desc_703 = {
          ContentES = "Inflige daño equivalente al <Highlight>50%</> de los PV Máx. del personaje a los enemigos dentro del alcance cada 3 s. Por cada disminución del <Highlight>25%</> de los PV, el efecto aumenta en un <Highlight>16.7%</>."
        },
        RLBlessingGroup_Desc_704 = {
          ContentES = "Cuando supera el <Highlight>40%</> de los PV, todos los efectos de [Flor vampírica] que escalan con el porcentaje de los PV actuales (incluidos Moral y Tenacidad) usan un valor limitado del <Highlight>40%</>."
        },
        RLBlessingGroup_Desc_unknown = {
          ContentES = "Esta bendición permanece envuelta en niebla."
        },
