        },
        RLBlessing_Desc_106 = {
          ContentES = "Recibir daño aplica <Highlight>1</> acumulación de [Llama fundida] a los enemigos en un radio de <Highlight>8</>m. Este efecto solo puede activarse una vez cada <Highlight>$1</> s."
