        },
        RLBlessing_Desc_112 = {
          ContentES = "Aumenta la Velocidad de ATQ de las armas cuerpo a cuerpo en <Highlight>#1</> y el rango de ATQ en <Highlight>#2</>."
        },
        RLBlessing_Desc_113 = {
          ContentES = "Si el daño reduce los PV de un objetivo por debajo de <Highlight>$3</>, inflige daño adicional equivalente al <Highlight>$1</> del ATQ del personaje. Este efecto solo puede activarse una vez cada <Highlight>$2</> s sobre el mismo objetivo."
        },
        RLBlessing_Desc_114 = {
          ContentES = "Las armas cuerpo a cuerpo infligen daño adicional equivalente al <Highlight>$1</> del ATQ del personaje a los objetivos afectados por más de <Highlight>$2</> acumulaciones de [Llama fundida]."
        },
        RLBlessing_Desc_115 = {
          ContentES = "Cuanto menos enemigos haya en un radio de <Highlight>8 metros</>, mayor será el Daño Infligido (hasta <Highlight>$1</>)."
