        },
        RLBlessing_Desc_203 = {
          ContentES = "Infligir daño con armas a distancia genera una [Caja de suministros de munición]. Este efecto solo puede activarse una vez cada <Highlight>$1</> s. Mientras [Luna marina] Fase II está activa, genera <Highlight>1</> [Mini Luna marina] adicional."
        },
        RLBlessing_Desc_204 = {
          ContentES = "Recoger objetos caídos otorga <Highlight>$1</> Escudos Ultras. Este efecto solo puede activar una vez cada <Highlight>$2</> s."
        },
        RLBlessing_Desc_205 = {
          ContentES = "Genera [Sal volátil activada] o [Gota de tranquilizante] al infligir daño. Este efecto solo puede activar una vez cada <Highlight>$1</> s. Mientras [Luna marina] Fase II está activa, genera <Highlight>1</> [Mini Luna marina] adicional."
        },
        RLBlessing_Desc_206 = {
          ContentES = "Si los enemigos se encuentran dentro de un radio de <Highlight>20</> m y la Fase III está activa, aumenta el ATQ del personaje en <Highlight>$1</>; de lo contrario, aumenta el ATQ del personaje en <Highlight>$2</>."
        },
        RLBlessing_Desc_207 = {
