        },
        RLBlessing_Desc_211 = {
          ContentES = "Reduce el tiempo de enfriamiento del Soporte de Geniemon en <Highlight>$1</>."
        },
        RLBlessing_Desc_212 = {
          ContentES = "Aumenta el multidisparo de las armas a distancia en <Highlight>#1</>."
        },
        RLBlessing_Desc_213 = {
          ContentES = "Aumenta la Velocidad de ATQ del arma a distancia en <Highlight>#1</>."
        },
        RLBlessing_Desc_214 = {
          ContentES = "Infligir daño a distancia a un objetivo situado a más de <Highlight>$2</> m aplica una penalización que aumenta el daño a distancia recibido en <Highlight>$1</>, hasta un máximo de <Highlight>$3</>."
        },
        RLBlessing_Desc_215 = {
          ContentES = "Moverse continuamente durante más de <Highlight>2</> s reduce el Daño Recibido en <Highlight>$1</> (hasta que se detenga).\nPermanecer quieto durante más de <Highlight>2</> s aumenta el Daño Infligido en <Highlight>$2</> (hasta que se mueva)."
        },
        RLBlessing_Desc_301 = {
