        },
        RLBlessing_Desc_310 = {
          ContentES = "Otorga <Highlight>$1</> acumulación(es) de <Highlight>[Destello]</> al usar habilidades."
        },
        RLBlessing_Desc_311 = {
          ContentES = "Mientras esté bajo [Resplandor], restaura ‍<Highlight>$1</>‍ de Cordura por segundo."
        },
        RLBlessing_Desc_312 = {
          ContentES = "Aumenta el Daño de Habilidad en <Highlight>#1</>."
        },
        RLBlessing_Desc_313 = {
          ContentES = "Ignora la DEF de los objetivos en <Highlight>$1</> al infligir Daño de Habilidad."
        },
        RLBlessing_Desc_314 = {
