        RLBlessing_Desc_406 = {
          ContentES = "Restaura la Cordura en <Highlight>$1</> al invocar invocaciones."
        },
        RLBlessing_Desc_407 = {
          ContentES = "Invoca 1 [Lumisemilla] cada <Highlight>$1</> s."
        },
        RLBlessing_Desc_408 = {
          ContentES = "Recibir daño tiene <Highlight>$1</> de probabilidad de invocar 1 [Lumisemilla]. Este efecto solo puede activarse una vez cada <Highlight>$2</> s."
        },
        RLBlessing_Desc_409 = {
          ContentES = "Reduce el Daño Recibido en <Highlight>$1</> cuando un objeto invocado se encuentra dentro de un rango de <Highlight>8</> metros."
        },
        RLBlessing_Desc_410 = {
