        },
        RLBlessing_Desc_414 = {
          ContentES = "Invocar una invocación que no sea Lumiramita provoca una explosión en su ubicación, lo que inflige daño equivalente al <Highlight>$1</> del ATQ."
        },
        RLBlessing_Desc_415 = {
