        },
        RLBlessing_Desc_501 = {
          ContentES = "Salto Espiral otorga +<Highlight>$1</> ATQ por <Highlight>$2</> s y <Highlight>$3</> acumulación(es) de [Devorador de sombras]."
        },
        RLBlessing_Desc_502 = {
          ContentES = "Al deslizarse se generan 3 [Alas de viento], cada una de las cuales inflige daño igual al <Highlight>$1</> del ATQ del personaje al impactar. También otorga <Highlight>$2</> acumulación(es) de [Devorador de sombras]."
        },
        RLBlessing_Desc_503 = {
