        },
        RLBlessing_Desc_506 = {
          ContentES = "Los Ataques Descendentes que infligen daño crean una zona de [Polvo de escama], que inflige cada segundo un daño equivalente al <Highlight>$2</> del ATQ del personaje a los enemigos dentro de ella, y otorga <Highlight>$3</> acumulaciones de [Devorador de sombras]. Este efecto solo puede activarse una vez cada <Highlight>$1</> s."
        },
        RLBlessing_Desc_507 = {
          ContentES = "Aumenta el Ataque Descendente en <Highlight>$1</>."
