        TERMEXP_1102_Passive01 = {
          ContentES = "Las unidades convertidas en [Marioneta del baile] no pueden actuar, lo que se considera un efecto de control."
        },
        TERMEXP_1102_Passive02 = {
          ContentES = "Consume todas las acumulaciones de [Espinas florales] para infligir daño de área Umbro. El multiplicador de daño aumenta según la cantidad de acumulaciones de [Espinas florales] consumidas. Este ataque se considera un Ataque Cargado de Arma Cuerpo a Cuerpo."
        },
        TERMEXP_1102_Skill01 = {
          ContentES = "Al golpear por primera vez a un enemigo con un ataque normal, consume 1 acumulación de [Sinfonía] para infligir daño de área Umbro adicional una vez frente ti, considerado Daño de Arma Cuerpo a Cuerpo.\nAl usar [Capítulo final], consume 5 acumulaciones de [Sinfonía] para infligir daño de área Umbro adicional 5 veces a tu alrededor, considerado Daño de Arma Cuerpo a Cuerpo."
        },
        TERMEXP_1102_Skill02 = {
          ContentES = "Consume 1 acumulación de [Bis] para generar una marioneta de alta velocidad en el borde del campo que inflige daño Umbro a los enemigos a su paso, se considera Daño de Arma Cuerpo a Cuerpo. Además, se obtiene 1 acumulación de [Espinas florales], con un máximo de 12.\nSi [Bis] no está activo o durante [Capítulo final], se obtiene 1 acumulación de [Bis]."
        },
        TERMEXP_1103_Combo = {
          ContentES = "Otorga cierta cantidad de [Inmersión]. Este efecto puede activarse como máximo una vez cada 0.1 s."
        },
        TERMEXP_1103_Finish = {
          ContentES = "Aumenta el daño según las acumulaciones de [Adagio] del objetivo y luego las elimina todas. Si el objetivo tiene 10 acumulaciones, restaura Cordura y otorga [Inmersión]. Se activa como máximo una vez por ataque."
        },
        TERMEXP_1103_HyperForm = {
          ContentES = "En [Furia Bestial: Devoción], consume [Inmersión] continuamente en lugar de Cordura para mantener el estado, aumenta la Velocidad de Habilidad y potencia el ATQ según la Cordura Máx. del usuario.\nMientras está activo [Furia Bestial: Devoción], no se obtiene [Inmersión] por mantener [Furia Bestial]."
        },
        TERMEXP_1103_Skill01 = {
          ContentES = "Se lanza hacia adelante, inflige Daño Umbro a los enemigos en su camino y obtiene [Presto]. [Presto]: Aumento de Rango de Habilidad; no sufre Aturdimiento al recibir daño."
        },
        TERMEXP_1201_Skill02 = {
          ContentES = "Daño Umbro adicional extra"
        },
        TERMEXP_1501_Buff01 = {
          ContentES = "No sufre Aturdimiento al recibir daño y el Daño Recibido se reduce."
        },
        TERMEXP_1502_Skill01 = {
          ContentES = "Crea 1 [Eclipse Solar] y reemplaza esta habilidad por [Cacería Lunar].\n[Eclipse Solar]: Al generarse, inflige Daño Lumino en el área y reduce el ATQ de los enemigos."
        },
        TERMEXP_1503_Skill02 = {
          ContentES = "Sale de [Manifestación de Aspecto] e inflige Daño Lumino a los enemigos frontales."
        },
        TERMEXP_1503_Skill02_01 = {
          ContentES = "Hereda las estadísticas del arma cuerpo a cuerpo de Kezhou y aumenta su rango de ataque. [Espada Phano] posee modos: Espada, Espadón, Arma de Asta y Hojas Dobles. Tras el último golpe del Ataque Normal de [Espada Phano], cambia a un modo aleatorio y lanza todas las [Pluma Phano]."
        },
        TERMEXP_1503_Skill02_02 = {
          ContentES = "Puede mantener hasta 7 [Pluma Phano] a la vez. Al lanzarse, cada [Pluma Phano] fija un enemigo aleatorio, orbita y se abalanza para atacar, lo que inflige Daño Lumino en trayectoria. Tras golpear 3 veces al objetivo, se disipa.\nLos objetivos alcanzados por [Pluma Phano] reciben un daño adicional equivalente a un porcentaje del Daño Periódico del efecto extra: Lumino, multiplicado por la Probabilidad de Activación del Arma Cuerpo a Cuerpo de Kezhou."
        },
        TERMEXP_1504_Passive_01 = {
          ContentES = "Cada acumulación eliminada restaura Cordura y aumenta la bonificación de daño de [Modelo Fengshi]."
        },
        TERMEXP_1504_Skill02_01 = {
          ContentES = "Otorga una bonificación de Moral."
        },
        TERMEXP_1504_Skill02_02 = {
          ContentES = "Los Ataques Normales con la [Gran espada del artificiero] consumen 10 proyectiles de la [Pólvora de artificiero] e infligen Daño Lumino a los enemigos en su trayectoria."
        },
        TERMEXP_1504_Skill02_03 = {
          ContentES = "Cada ataque consume 1 [Pólvora de artificiero] para disparar un proyectil que inflige Daño Lumino en el área al impactar.\nCuando se equipa la Cuña Demoníaca [Fengshi tipo III: modo rastreo], este ataque dispara en su lugar proyectiles guiados que buscan enemigos aleatorios e infligen Daño Lumino en el área cada 0.1 s a lo largo de su recorrido."
        },
        TERMEXP_1601_Skill02 = {
          ContentES = "Aumenta el Daño de Arma."
        },
        TERMEXP_1801_Passive = {
          ContentES = "Inflige Daño Lumino adicional."
        },
        TERMEXP_1801_Skill02 = {
          ContentES = "Genera un campo elemental según los [Invitados del Té Escandaloso]: [Ruiseñor] (Hydro), [Sabueso] (Pyro), [Unicornio] (Electro) y [Mariposa] (Anemo).\nAl aparecer o cambiar el elemento del campo, Fina y sus aliados obtienen daño adicional según el atributo del campo. Mientras [Fiesta de Té Escandalosa] está activa, inflige Daño Periódico elemental cada 2 s a los enemigos dentro del área."
        },
        TERMEXP_2101_Dot = {
          ContentES = "Inflige Daño Periódico Hydro cada 2 s. Al ser derrotado, un enemigo con [Veneno de Amor] contagia su efecto a los cercanos según sus acumulaciones y duración restante."
        },
        TERMEXP_2101_Summon = {
          ContentES = "Hereda el 100% de las estadísticas de Rebecca y ataca continuamente a los enemigos cercanos con Daño Hydro."
        },
        TERMEXP_2301_Summon = {
          ContentES = "Hereda el 100% de las estadísticas de Tabethe, infligiendo continuamente Daño Hydro a los enemigos cercanos y capturando hasta 2 enemigos para inmovilizarlos."
        },
        TERMEXP_2401_Skill02Buff = {
          ContentES = "Aumenta el Daño de Habilidad en un porcentaje del Daño de Habilidad de [Fushu]."
        },
        TERMEXP_2401_Summon = {
          ContentES = "Hereda el 100% de las estadísticas de Fushu e inflige Daño Hydro una vez por segundo a los 5 enemigos más cercanos.\nCada 3 s, [Yunchi] restaura PV y Cordura a aliados cercanos."
        },
        TERMEXP_3101_Debuff = {
          ContentES = "Bajo la influencia de [Laceración], cada vez que el enemigo recibe daño de armas a distancia de [Lynn], el recuento de [Herida Lacerada] aumenta en 1. Al finalizar la duración de [Laceración], inflige Daño Pyro equivalente al recuento de [Herida Lacerada] × daño de [Laceración] al enemigo una vez."
        },
        TERMEXP_3102_Buff = {
          ContentES = "Aumenta la Velocidad de Ataque de [Desempolvador], la Velocidad de Rotación de [Limpieza por Pirólisis] y la Velocidad de Ataque de las armas a distancia."
        },
        TERMEXP_3102_Debuff = {
          ContentES = "Desactiva permanentemente las armas a distancia."
        },
        TERMEXP_3103_Skill02 = {
          ContentES = "Al estar en el área de [Laboratorio de Pesadilla]: la Velocidad de Movimiento de los enemigos dentro del alcance disminuye. Los temporizadores de detonación de los [Pequeño Bum] en el suelo se pausan y no serán detonados por otros [Pequeño Bum].\nAl cerrar [Laboratorio de Pesadilla]: detona todos los [Pequeño Bum] dentro del alcance y el laboratorio explota, lo que inflige Daño Pyro a los enemigos dentro del alcance. Por cada [Pequeño Bum] detonado, aumenta el daño explosivo de [Laboratorio de Pesadilla] y restaura la Cordura de Yale y Oliver."
        },
        TERMEXP_3103_Summon01 = {
          ContentES = "Al infligir daño, causa una mayor reducción de Postura al objetivo. Cuanto mayor sea la diferencia entre el Daño de Habilidad de Yale y Oliver y el Rango de Habilidad, mayor será la probabilidad de activación de desplegar [Pequeño Bum: Creado por Yale]. Si la diferencia es superior o igual al 50%, se garantiza que será un [Pequeño Bum: Creado por Yale]."
        },
        TERMEXP_3103_Summon02 = {
          ContentES = "Inflige mayor daño. Cuanto mayor sea la diferencia entre el Rango de Habilidad de Yale y Oliver y el Daño de Habilidad, mayor será la probabilidad de activación de desplegar [Pequeño Bum: Creado por Oliver]. Si la diferencia es superior o igual al 50%, se garantiza que será un [Pequeño Bum: Creado por Oliver]."
        },
        TERMEXP_3201_Skill01 = {
          ContentES = "Inflige Daño Pyro a los enemigos cercanos una vez cada 2 s. Si Hellfire recibe daño durante la duración, prolonga el efecto e inflige Daño Pyro adicional [Retribución por Punzada] a los enemigos cercanos una vez cada 2 s."
        },
        TERMEXP_3202_Passive01 = {
          ContentES = "Al infligir Daño Pyro, excepto el daño de [Hojas de sumiller] y [Herida carmesí], a objetivos afectados por [Herida carmesí], se elimina 1 acumulación de [Herida carmesí] y se inflige 1 instancia adicional de Daño Pyro de [Camilla]. No se pueden eliminar más de 20 acumulaciones del mismo objetivo por segundo."
        },
        TERMEXP_3202_Skill01 = {
          ContentES = "Aumenta la Velocidad de Habilidad y la velocidad de lanzamiento de [Hojas de sumiller]. Mientras [Achispado] está activo, el temporizador de duración de [Hojas de sumiller] se pausa y Camilla se vuelve inmune al Aturdimiento."
        },
        TERMEXP_3202_Skill02 = {
          ContentES = "Mientras orbitan al personaje, las [Hojas de sumiller] infligen daño a los enemigos que se crucen en su trayectoria.\n Al ser lanzadas, recorren una distancia fija antes de regresar, e infligen daño tanto a la ida como a la vuelta.\n Si [Banquete Escarlata] las golpea mientras están regresando, se lanzan de nuevo hacia un objetivo cercano aleatorio."
        },
        TERMEXP_4101_Skill02_01 = {
          ContentES = "Aumenta la Velocidad de Movimiento propia y de sus aliados. Cada segundo, inflige Daño Electro a un enemigo aleatorio dentro del alcance y alterna entre [Carga Positiva] y [Carga Negativa]. Prioriza a los enemigos sin [Carga Eléctrica]."
        },
        TERMEXP_4101_Skill02_02 = {
          ContentES = "El objetivo con [Carga Positiva] selecciona 1 objetivo aleatorio con [Carga Negativa] dentro del alcance cada 3 s; ambos son atraídos hacia el punto medio entre sus posiciones y reciben Daño Electro. Si no hay objetivos con [Carga Negativa] cerca, selecciona un objetivo aleatorio; ambos reciben Daño Electro.\nCuando un objetivo con [Carga Eléctrica] recibe el mismo tipo de carga de nuevo, la duración de la [Carga Eléctrica] se actualiza; no se le puede aplicar el tipo opuesto de [Carga Eléctrica]."
        },
        TERMEXP_4102_Skill02_01 = {
          ContentES = "Cuando tiene 2 [Talismánes: Zhen], [Adivinación Cielo-Tierra] se reemplaza por esta habilidad.\nElimina todos los [Talismánes]. Inflige Daño Electro a los enemigos en línea recta frontal."
        },
        TERMEXP_4102_Skill02_02 = {
          ContentES = "Al tener 1 [Talismán: Zhen] y 1 [Talismán: Xun], [Adivinación Cielo-Tierra] se reemplaza con esta habilidad.\nElimina todos los [Talismánes]. Inflige daño continuamente a los enemigos en una zona frontal y luego crea un campo de [Armonía de los Cuatro Reinos] en la ubicación dañada. Cada 3 s, selecciona hasta 5 enemigos dentro del campo para crear un [Convergencia Zhen-Xun] en su ubicación, lo que inflige Daño Electro en un área de efecto."
        },
        TERMEXP_4102_Skill02_03 = {
          ContentES = "Cuando tiene 2 [Talismánes: Xun], [Adivinación Cielo-Tierra] se reemplaza con esta habilidad.\nElimina todos los [Talismánes]. Inflige Daño Electro a los enemigos cercanos y aumenta el Daño de Habilidad del usuario."
        },
        TERMEXP_4201_BonusAttack = {
          ContentES = "Genera [Truenos Furiosos] en los objetivos alcanzados por [Descenso de Luz Estelar] o [Descenso de Tormenta Estelar] e inflige Daño Electro de área. Se puede seleccionar un máximo de 5 objetivos."
        },
        TERMEXP_4201_FallAttack = {
          ContentES = "Se lanza en picado a gran velocidad y causa Daño Electro de área al impactar. Este ataque se considera un Ataque Descendente de arma cuerpo a cuerpo. Usar esta habilidad en el estado [Encarnación de Xuanjiao] activa [Nubes Dracónicas]."
        },
        TERMEXP_4201_Marks = {
          ContentES = "Persiste, con un máximo de 6 escamas existentes simultáneamente. Las escamas se eliminan al finalizar el estado [Encarnación de Xuanjiao]."
        },
        TERMEXP_4201_Skill2Buff = {
          ContentES = "Los objetivos afectados por [Asalto Tronante] reciben 1 instancia adicional de Daño Electro de [Yuming] cuando son dañados por [Yuming] o por aliados Electro. Puede activarse sobre el mismo objetivo una vez cada 2 s."
        },
        TERMEXP_4201_Summon = {
          ContentES = "Inmune al Aturdimiento por golpe. El Xuanjiao flota alrededor de [Yuming].\nEl Xuanjiao absorbe el daño de PV infligido a [Yuming]. Cuando la cantidad absorbida alcanza un porcentaje determinado de los PV Máx. de [Yuming], [Encarnación de Xuanjiao] finaliza."
        },
        TERMEXP_4201_SuperFallAttack = {
          ContentES = "Consume todas las [Escamas Inversas] y se aplica un Aumento de Daño Infligido.\n Luego se lanza en picada a gran velocidad e inflige daño Electro en el área al impactar. Este ataque cuenta como un Ataque Descendente de Arma Cuerpo a Cuerpo. Mientras [Manifiesto del Dragón Oscuro] está activo, también activa [Nubes Dracónicas]."
        },
        TERMEXP_4202_Skill01 = {
          ContentES = "[Barrera] bloquea proyectiles frontales y absorbe su daño. Expira al absorber daño equivalente al 100% de los PV Máx. de Randy."
        },
        TERMEXP_4202_Skill01Buff = {
          ContentES = "Disminuye el ATQ e inflige Daño Electro una vez cada 2 s."
        },
        TERMEXP_4301_Skill01 = {
          ContentES = "Tras 1.5 segundos de generarse, consume ciertos puntos de [Poder del Trueno] cada 0.4 s para infligir Daño Electro a 1 enemigo aleatorio dentro del rango del campo, con una duración de hasta 10 s. Cuando [Poder del Trueno] se agota a 0, el campo de [Castigo de Legión] se disipa. Pueden existir un máximo de 3 campos de [Castigo de Legión] a la vez."
        },
        TERMEXP_4301_Skill02 = {
          ContentES = "Hereda un cierto porcentaje de los PV Máx. de Sibylle, tiene 0 DEF y es tratada como una unidad enemiga.\nTras ser invocada, [Orbe Trueno de Caótico] activa [Tormenta Devastadora] una vez cada 3 s.\nTras ser invocada, [Orbe Trueno de Caótico] se vincula a los 5 enemigos más lejanos dentro de su rango y vincula a 1 enemigo adicional por segundo, hasta un total de 10 enemigos vinculados simultáneamente. [Orbe Trueno de Caótico] inflige Daño Electro a los objetivos vinculados una vez por segundo.\nCuando [Orbe Trueno de Caótico] recibe daño, un cierto porcentaje del daño se transfiere a los objetivos vinculados."
        },
        TERMEXP_4301_Skill02Damage = {
          ContentES = "Inflige Daño Electro a los enemigos cercanos."
        },
        TERMEXP_5101_Skill01 = {
          ContentES = "Mantén pulsada la habilidad para consumir Cordura continuamente mientras montas a [Filbert] en una carga continua, lo que inflige Daño Anemo a los enemigos en el camino. La carga se detiene al chocar con un obstáculo e inflige Daño Anemo en área."
        },
        TERMEXP_5101_Skill02_Value = {
          ContentES = "[Pasión por el Trabajo] disminuye 5 puntos por segundo y restaura 1 al infligir daño por impacto. Durante [Trotadores Carga-Carga], [Pasión por el Trabajo] no disminuirá. Cuando [Pasión por el Trabajo] llega a 0, desmonta y libera [Trotadores Trota-Trota] una vez."
        },
        TERMEXP_5102_Skill01 = {
          ContentES = "En estado [Sigilo], no puede ser detectado por los enemigos y recibir daño no lo hará salir del estado [Sigilo]. Atacar o usar [Ataque del Depredador] hará que salga del estado [Sigilo]."
        },
        TERMEXP_5102_Skill02 = {
          ContentES = "En el estado [Caza Implacable], es inmune al Aturdimiento al recibir daño y obtiene aumento de Velocidad de Ataque con armas y Tenacidad. En estado [Caza Implacable], no puede recibir curación. La curación se convierte en una cantidad equivalente de Escudo Ultra."
        },
        TERMEXP_5102_Skill03 = {
          ContentES = "Tras generarse, vuela hacia el objetivo e inflige Daño Anemo a los enemigos en su camino, inflige [Corta Gargantas]: aumenta el daño recibido de Outsider. Tras volar durante un tiempo, cae al suelo y permanece allí. Pueden existir un máximo de 10 simultáneamente."
        },
        TERMEXP_5301_Skill01 = {
          ContentES = "Se proyecta hacia adelante y dispara 16 [Polvos Etéreos]. Los [Polvos Etéreos] se fijan automáticamente en 1 enemigo aleatorio tras ser disparados, infligen Daño Anemo al impactar y aplican 1 acumulación de [Estigma de Polvo], hasta un máximo de 12 acumulaciones."
        },
        TERMEXP_5301_Skill01Mark = {
          ContentES = "Cuando un objetivo con [Estigma de Polvo] recibe daño de arma a distancia de [Psyche], se consume 1 acumulación de [Estigma de Polvo] para infligir Daño Anemo una vez."
        },
        TERMEXP_5301_Summon = {
          ContentES = "Tras generarse, aplica continuamente disminución de Velocidad de Movimiento a los enemigos cercanos. Tras 5 s, inflige Daño Anemo a los enemigos cercanos una vez y desaparece. Al generar un [Fantasma], hace que los [Fantasma] ya generados en el campo ejecuten inmediatamente el efecto de daño y desaparezcan."
        },
        TERMEXP_5401_Buff = {
          ContentES = "Obtiene Daño Anemo adicional."
        },
        TERMEXP_5401_Debuff = {
          ContentES = "Disminuye el ATQ y recibe Daño Periódico Anemo cada 2 s."
        },
        TERMEXP_Common_AdditionalDmg = {
          ContentES = "Al infligir daño con un arma, según el valor de ese daño, inflige una vez daño adicional del atributo especificado y verifica la activación de efectos extra según la Probabilidad de Activación del arma."
        },
        TERMEXP_Common_OverES = {
          ContentES = "Un escudo adicional que se acumula independientemente del escudo. El Escudo Ultra tiene un límite de 425 + 75 × nivel del personaje."
        },
        TERMEXP_Common_SkillSpeed = {
          ContentES = "Determina la rapidez de ejecución de las habilidades que tienen animación de lanzamiento."
