        Title_Des = {
          ContentES = "Equípalo en [Título]"
        },
        Toast_Access_HardBossUnlock = {
          ContentES = "Los Ecos nocturnos para esta dificultad no están desbloqueados."
        },
        Toast_DonglishiJiaoxue = {
          ContentES = "Ataca las Ruedas Phoxynamo activas para apagarlas"
        },
        Toast_MiYao = {
          ContentES = "Llave recuperada con éxito"
        },
        Toast_PaoJi = {
          ContentES = "Paso abierto. Sal de la torreta y avanza hacia la sala de control central"
        },
        Toast_SewWarning = {
