          ContentES = "Ataque cargado"
        },
        UIGUIDE_TITLE_EXECUTION_01 = {
          ContentES = "Mecánicas de combate: Postura"
        },
        UIGUIDE_TITLE_EXECUTION_02 = {
          ContentES = "Mecánicas del personaje: \"Retribución de Ask\""
        },
        UIGUIDE_TITLE_FALLATTACK = {
          ContentES = "Ataque Descendente"
        },
