          ContentES = "Arma a Distancia"
        },
        UIGUIDE_TITLE_HPSHIELD = {ContentES = "Escudo/PV"},
        UIGUIDE_TITLE_PARTIALDAMAGE = {
          ContentES = "Mecánicas de combate: Divide y destruye"
        },
        UIGUIDE_TITLE_SIDEWAYSJUMP = {
          ContentES = "Ascenso lateral"
        },
        UIGUIDE_TITLE_SKILL2_01 = {
          ContentES = "Habilidad Definitiva del personaje: Llama Infernal"
