        UIGUIDE_TITLE_WIKI = {ContentES = "Atlasium"},
        UIGuide_Abyss_1 = {
          ContentES = "Acciona el dispositivo para iniciar el desafío de Teatro inmersivo."
        },
        UIGuide_Abyss_2 = {
          ContentES = "Cuando se alza el telón, los intérpretes disfrazados como enemigos suben al escenario. Derrota la cantidad requerida de enemigos dentro del límite de tiempo para continuar."
        },
        UIGuide_Abyss_3_1 = {
          ContentES = "Victoria: Elimina la cantidad objetivo de enemigos dentro del límite de tiempo para desbloquear la siguiente etapa."
        },
        UIGuide_Abyss_3_2 = {
          ContentES = "Fracaso: Si no logras cumplir el objetivo, el desafío terminará inmediatamente."
        },
        UIGuide_Abyss_4 = {
          ContentES = "Una vez que se abra el camino, avanza a la siguiente etapa antes de que termine la cuenta regresiva — o el desafío fracasará."
        },
        UIGuide_Abyss_5 = {
          ContentES = "El quinto y último acto presenta enemigos de alta dificultad. Derrótalos dentro del límite de tiempo para completar el Teatro inmersivo."
        },
        UIGuide_AnHao_1 = {
          ContentES = "Para mantenerse en contacto, los Vagabundos han dejado señales cifradas con forma de ave en las paredes rocosas de las Afueras orientales."
        },
        UIGuide_AnHao_2 = {
          ContentES = "Atacar una señal cifrada libera un mecaave fantasma que vuela al siguiente lugar y crea otra señal.\n Sigue las marcas para encontrar la señal que dejaron los Vagabundos.\n Si hay enemigos cerca, atacar la señal no tendrá efecto."
        },
        UIGuide_Appearance_1 = {
          ContentES = "Coleccionar cosméticos o teñirlos aumenta el punto de esplendor"
        },
        UIGuide_Appearance_2 = {
          ContentES = "Al aumentar el punto de esplendor, puedes obtener recompensas"
        },
        UIGuide_Appearance_3 = {
          ContentES = "Al aumentar el punto de esplendor, podrás mostrar tu estilo en la clasificación de esplendor"
        },
        UIGuide_AssistanceSkill = {
          ContentES = "Los <H>Geniemons</> proveen una variedad de asistencias de combate."
        },
        UIGuide_AutoChess_1 = {
          ContentES = "Tu tablero está en primer plano y el del enemigo al fondo.\nAntes de que empiece la partida, puedes observar el despliegue de Mecatíteres del enemigo y colocar tus propias unidades en tu lado en consecuencia.\nCuando la partida empiece, todos los Mecatíteres combatirán automáticamente hasta que uno de los bandos sea eliminado por completo.\nLa victoria se consigue derrotando a todos los Mecatíteres enemigos."
        },
        UIGuide_AutoChess_2_1 = {
          ContentES = "Para desplegar un Mecatítere, selecciona uno que tengas y haz clic en un espacio vacío del tablero."
        },
        UIGuide_AutoChess_2_2 = {
          ContentES = "Selecciona un Mecatítere aliado desplegado en el tablero para recolocarlo o retirarlo.\nSelecciona cualquier Mecatítere para ver sus detalles."
        },
        UIGuide_AutoChess_2_3 = {
          ContentES = "Desplegar Mecatíteres consume Carga. La Carga total de los Mecatíteres desplegados en tu tablero no puede superar el límite."
        },
        UIGuide_AutoChess_3 = {
          ContentES = "Aquí puedes consultar el <H>Potencial estratégico</> de cada tablero."
        },
        UIGuide_AutoChess_4_1 = {
          ContentES = "Usa <H>Restablecer formación</> para retirar todos tus Mecatíteres desplegados."
        },
        UIGuide_AutoChess_4_2 = {
          ContentES = "Usa <H>Preajustes de formación</> para guardar tu despliegue actual de Mecatíteres y sus posiciones.\nLos Preajustes de formación no guardan las Runas equipadas en los Mecatíteres."
        },
        UIGuide_AutoChess_5 = {
          ContentES = "Cuando tu formación esté lista, ya puedes <H>iniciar la partida</>."
        },
        UIGuide_BattleWheel_1 = {
          ContentES = "La <H>mochila táctica</> es vital para el combate. Te permite <H>invocar aliados</> y <H>usar objetos</> para obtener una ventaja táctica.\nTambién puedes agregar <H>Posturas</> a la Mochila táctica desde la página de <H>Arsenal</>."
        },
        UIGuide_BattleWheel_2_PC = {
          ContentES = "Mantén &OpenBattleWheel& para invocar a un Compañero de combate, que luchará junto a tu personaje actual."
        },
        UIGuide_BattleWheel_2_Phone = {
          ContentES = "Pulsa el botón para invocar a un Compañero de combate, que luchará junto a tu personaje actual."
        },
        UIGuide_Biography = {
          ContentES = "Las historias populares ofrecen historias de fondo de personas de todo el mundo. Podrás acceder a estas historias una vez que los conozcas mejor."
        },
        UIGuide_BonusDamage = {
          ContentES = "Al infligir daño con un arma, se inflige daño adicional <H>una vez</> según el tipo y cantidad de daño original causado. El daño adicional puede activar el efecto adicional correspondiente según la <H>probabilidad de activación del arma</>."
        },
        UIGuide_BulletJump_1_PC = {
          ContentES = "Mantén presionado &Slide& y luego presiona &Jump& para realizar un Salto Espiral sobre precipicio o recorrer largas distancias"
        },
        UIGuide_BulletJump_1_Phone = {
          ContentES = "Mantén presionado el botón de salto y <H>desliza hacia arriba</> para realizar un Salto Espiral sobre precipicio o cubrir largas distancias."
        },
        UIGuide_BulletJump_2 = {
          ContentES = "Inclina la cámara hacia arriba y usa el Salto Espiral para llegar a áreas <H>elevadas</>."
        },
        UIGuide_ChangeElem_1 = {
          ContentES = "En <H>Arsenal</> puedes cambiar los atributos del Phoxcazador."
        },
        UIGuide_ChenMo_1 = {
          ContentES = "Bajo el efecto de el Azote de Zhuyin, algunos personajes, cofres y mecanismos del Puerto de las Brumas están sepultados bajo el <H>Polvo corrompido</>. En este estado, toda interacción es imposible."
        },
        UIGuide_ChenMo_2 = {
          ContentES = "Utiliza la función Atracción del Nexo Mecánico para disipar el <H>Polvo corrompido</>."
        },
        UIGuide_Chest_1 = {
          ContentES = "Ciertos cofres requieren una <H>llave</> para ser abiertos. Mantente atento a las llaves dispersas a lo largo de tu viaje."
        },
        UIGuide_Combo_01 = {
          ContentES = "Cada vez que inflijas daño a un enemigo con un <H>arma cuerpo a cuerpo</>, obtendrás 1 <H>punto de combo</>. Obtén cierta cantidad de puntos de combo para incrementar tu <H>Nivel del Combo</>."
        },
        UIGuide_Combo_02_PC = {
          ContentES = "Mantén &Attack& para ejecutar un <H>Ataque Cargado</>. El daño de este Ataque Cargado aumentará de acuerdo al <H>Nivel del Combo actual</>, y luego los <H>puntos de combo se reiniciarán a 0</>."
        },
        UIGuide_Combo_02_Phone = {
          ContentES = "Mantén el botón para ejecutar un <H>Ataque Cargado</>. El daño de este Ataque Cargado aumentará de acuerdo al <H>Nivel del Combo actual</>, y luego los <H>puntos de combo se reiniciarán a 0</>."
        },
        UIGuide_ConnectMechanism = {
          ContentES = "Un mecanismo de cerradura de puerta común. Arrastra la pieza hexagonal a lo largo del camino correcto hasta el punto final dentro del tiempo asignado para desbloquear este tipo de cerradura mágica."
        },
        UIGuide_Conveyor_1 = {
          ContentES = "En la cinta transportadora de las instalaciones de forja, a veces sale vapor a alta temperatura que impide avanzar."
        },
        UIGuide_Conveyor_2 = {
          ContentES = "Cuando una pieza pase por la cinta transportadora, aprovecha el momento en que bloquea el vapor para cruzar."
        },
        UIGuide_Conveyor_3 = {
          ContentES = "Cuando el indicador del interruptor esté en rojo, la cinta transportadora está detenida."
        },
        UIGuide_Conveyor_4 = {
          ContentES = "Ataca el interruptor para poner en marcha la cinta transportadora."
        },
        UIGuide_CursorActivation = {
          ContentES = "Mantén &ShowCursor& para mostrar el cursor e interactuar con los iconos de la página."
        },
        UIGuide_DamageMechanism_1 = {
          ContentES = "Los mecanismos de autodefensa atacan a <H>todas las unidades</> dentro del alcance."
        },
        UIGuide_DamageMechanism_2 = {
          ContentES = "Pueden ser evitados o neutralizados."
        },
        UIGuide_Deduce_1 = {
          ContentES = "Analiza una o más pistas para descubrir nuevas pistas."
        },
        UIGuide_Deduce_2 = {
          ContentES = "Presenta pistas clave para completar la deducción."
        },
        UIGuide_Deduce_SubTitle_1 = {ContentES = "Meditar"},
        UIGuide_Deduce_SubTitle_2 = {
          ContentES = "Presentar pista"
        },
        UIGuide_Delivery_01 = {
          ContentES = "Acércate para invocar el Ave espiritual onírica y registrar la ubicación actual."
        },
        UIGuide_Delivery_01_phone = {
          ContentES = "Acércate para invocar el Ave espiritual onírica y registrar la ubicación actual."
        },
        UIGuide_Delivery_02 = {
          ContentES = "Pulsa&OpenMap& para abrir el mapa y <H>teletransportarte</> a cualquier ubicación registrada."
        },
        UIGuide_Delivery_02_phone = {
          ContentES = "Abre el mapa y selecciona una ubicación registrada para <H>teletransportarse</> allí."
        },
        UIGuide_DengHua_1 = {
          ContentES = "<H>Flores-linterna</> están dispersas por la Grieta del Olvido, portando las oraciones de los vivos. Bajo su luz, recuperas gradualmente PV y estás protegido de la erosión de la Grieta del Olvido."
        },
        UIGuide_Destructible = {
          ContentES = "Algunos objetos pueden ser dañados al ser atacados. Puedes encontrar suministros ocultos en ellos..."
        },
        UIGuide_DianFeng_1 = {
          ContentES = "Durante la Clasificación suprema, los Phoxcazadores se enfrentan a <H>enemigos de amenaza extrema</> además de oleadas de enemigos <H>mucho más peligrosos de lo habitual</>."
        },
        UIGuide_DianFeng_2 = {
          ContentES = "Los enemigos de amenaza extrema tienen un PV excepcionalmente alto. Derrotar unidades normales reduce su PV."
        },
        UIGuide_DianFeng_3 = {
          ContentES = "Derrota a los enemigos de amenaza extrema dentro del tiempo límite para asegurar tu posición en la Clasificación suprema."
        },
        UIGuide_DianFeng_4 = {
          ContentES = "Los Phoxcazadores obtienen puntos de clasificación según PV restante de los enemigos de amenaza extrema y el tiempo disponible."
        },
        UIGuide_Dodge_PC = {
          ContentES = "Presiona &Avoid& para esquivar ataques entrantes. Solo puedes esquivar un <H>número limitado de veces</> dentro de un periodo de tiempo específico. Las esquivas consecutivas son posibles cuando tienes suficientes intentos de esquiva."
        },
        UIGuide_Dodge_Phone = {
          ContentES = "Pulsa el botón para esquivar ataques entrantes. Solo puedes esquivar un <H>número limitado de veces</> dentro de un periodo de tiempo específico. Las esquivas consecutivas son posibles cuando tienes suficientes intentos de esquiva."
        },
        UIGuide_Dot = {
          ContentES = "Inflige daño <H>una vez</> cada <H>2 s</> durante su duración. El Daño Periódico <H>no puede</> activar los Efectos Adicionales."
        },
        UIGuide_DynStory_1 = {
          ContentES = "De vez en cuando, Misiones dinámicas aparecerán por el mundo. Tu participación puede alterar el resultado."
        },
        UIGuide_DynStory_2 = {
          ContentES = "En algunas Misiones dinámicas, tus elecciones afectarán a tus Cinco Impresiones."
        },
        UIGuide_EX01Map = {
          ContentES = "En el <H>Mapa</>, selecciona la <H>esquina superior derecha</> para abrir el <H>Mapa mundial</> donde puedes intercambiar entre el <H>Capítulo Noctoviajero</> y el <H>Capítulo Crepúsculo</>."
        },
        UIGuide_EX01Mechanism_1 = {
          ContentES = "Interactúa con los <H>transformadores</> para <H>activar o desactivar</> sus dispositivos conectados. Comprueba el color de los <H>cables</> para diferenciar qué dispositivos están <H>activos</>."
        },
        UIGuide_EX01Mechanism_2 = {
          ContentES = "Comprueba el color de los <H>cables</> conectados para determinar sus estados: <H>Azul</>: El <H>dispositivo</> está activo. <H>Naranja</>: El dispositivo está <H>inactivo</>. Busca los transformadores necesarios cerca para activarlo."
        },
        UIGuide_Elevator = {
          ContentES = "Los elevadores son mecanismos estándar para el transporte vertical."
        },
        UIGuide_ExplorationMechanism_1_PC = {
          ContentES = "Lunoexploradora ha preparado desafíos en todo el mundo. Acércate a uno y presiona &Interactive& para iniciar el desafío."
        },
        UIGuide_ExplorationMechanism_1_Phone = {
          ContentES = "Lunoexploradora ha preparado desafíos en todo el mundo. Acércate a uno e <H>interactúa</> con él para iniciar el desafío."
        },
        UIGuide_ExplorationMechanism_2 = {
          ContentES = "Completa el desafío siguiendo la guía para llegar al objetivo dentro del tiempo especificado."
        },
        UIGuide_ExplorationMechanism_3 = {
          ContentES = "Completa el desafío siguiendo la navegación para disparar a los objetivos designados dentro del límite de tiempo."
        },
        UIGuide_FanZhuan_1 = {
          ContentES = "Interactúa con el mecanismo de rotación hace girar horizontalmente los bloques de piedra a ambos lados de la puerta, revelando su cara decorada con motivos."
        },
        UIGuide_FanZhuan_2 = {
          ContentES = "Una nueva interacción provoca una rotación adicional, revelando la cara con anillos. Utiliza la función Atracción del Nexo Mecánico para extraer el bloque decorado y desbloquear el cofre."
        },
        UIGuide_FangShu_1 = {
          ContentES = "El Nexo Mecánico puede equiparse e invocarse desde la <H>Mochila táctica</>."
        },
        UIGuide_FangShu_2 = {
          ContentES = "Después de invocar el Nexo Mecánico, mantén &Fire& para entrar en modo Atracción e interactuar con los mecanismos de la Secta Jishu."
        },
        UIGuide_FangShu_2_Phone = {
          ContentES = "Tras invocar el Nexo mecánico, mantén pulsado el botón para activar el modo Atracción e interactuar con los mecanismos de la Secta Jishu."
        },
        UIGuide_FangShu_3 = {
          ContentES = "Después de invocar el Nexo Mecánico, pulsa &Skill3& para escanear los mecanismos interactivos cercanos."
        },
        UIGuide_FangShu_3_Phone = {
          ContentES = "ras invocar el Nexo mecánico, pulsa el botón para escanear los mecanismos interactivos cercanos."
        },
        UIGuide_FangShu_4 = {
          ContentES = "Después de invocar el Nexo mecánico, abre de nuevo la Mochila táctica y selecciona el Nexo mecánico para recuperarlo. Una vez retirado, los ataques a distancia y las habilidades de Geniemon estarán nuevamente disponibles."
        },
        UIGuide_Feina_1 = {
          ContentES = "En este cuento inconcluso, todo está en escala de grises. Haz clic en &Fire& para pintar el mundo con <H>Pigmento Tejesueños</> y darle color al relato."
        },
        UIGuide_Feina_10 = {
          ContentES = "Observa el <H>entorno</> de cada gema y píntala con el color correcto para encender su luz y disipar las nieblas."
        },
        UIGuide_Feina_11 = {
          ContentES = "Absorber la energía de una gema forma un aura protectora alrededor del pequeño Ruiseñor, protegiéndolo de las nieblas. El aura se desvanece con el tiempo, ilumina gemas rápidamente para renovar su fuerza."
        },
        UIGuide_Feina_12 = {
          ContentES = "Golpea un disco grabado con pigmento <H>del color correspondiente</> para romperlo y abrir el camino."
        },
        UIGuide_Feina_1_Phone = {
          ContentES = "En este cuento inconcluso, todo está en escala de grises. Pulsa para pintar el mundo con <H>Pigmento Tejesueños</> y darle color al relato."
        },
        UIGuide_Feina_2 = {
          ContentES = "<H>Plumas blancas</> están esparcidas por el reino de cuento. Reúne suficientes para obtener recompensas extra."
        },
        UIGuide_Feina_3 = {
          ContentES = "Algunos dispositivos solo pueden activarse con ciertos colores. Haz clic en &ChargeBullet& para cambiar entre pigmentos."
        },
        UIGuide_Feina_3_Gamepad = {
          ContentES = "Algunos dispositivos solo pueden activarse con un color específico. Presiona &GamepadUseSkill& + &Fire& para alternar entre diferentes pigmentos."
        },
        UIGuide_Feina_3_Phone = {
          ContentES = "Algunos dispositivos solo pueden activarse con ciertos colores. Pulsa el botón para cambiar entre pigmentos."
        },
        UIGuide_Feina_4 = {
          ContentES = "Algunas flores permanecen sin color. Observa flores cercanas de <H>la misma forma</> y píntalas con el color correspondiente."
        },
        UIGuide_Feina_5 = {
          ContentES = "Algunas flores perderán su color tras un tiempo. <H>Píntalas todas correctamente a tiempo</> para activar el mecanismo."
        },
        UIGuide_Feina_6 = {
          ContentES = "Aplica un pigment a la palangana para que emita luz mágica del mismo color. Observa el entorno y usa <H>el color correcto</> para activar el mecanismo."
        },
        UIGuide_Feina_7 = {
          ContentES = "Sigue el brillo de la gema y <H>pinta todas las espinas con el color correcto</> para despejar las ramas entrelazadas."
        },
        UIGuide_Feina_8 = {
          ContentES = "Una vez que todas las espinas estén coloreadas, el pequeño Ruiseñor usará el poder de la gema para ayudar a Fina a abrir el camino."
        },
        UIGuide_Feina_9 = {
          ContentES = "Nieblas peligrosas invaden el bosque. Si permaneces demasiado tiempo, Fina perderá el rumbo."
        },
        UIGuide_FenZuSai_1 = {
          ContentES = "Durante la Fase de grupos, los Phoxcazadores se enfrentan a oleadas de enemigos <H>mucho más peligrosos de lo habitual</>."
        },
        UIGuide_FenZuSai_2 = {
          ContentES = "Derrotar el número requerido de enemigos dentro del tiempo establecido permite superar la Fase de grupos."
        },
        UIGuide_FenZuSai_3 = {
          ContentES = "Los Phoxcazadores obtienen puntos de clasificación según el número de enemigos derrotados y el tiempo restante."
        },
        UIGuide_FireMechanism = {
          ContentES = "Las <H>Trampas de llamas</> se <H>activarán</> al ser atacadas, infligiendo daño a <H>todos los objetivos</> que las atraviesen. Algunas <H>Trampas de llamas</> infligen daño más alto, pero requieren más tiempo de recarga."
        },
        UIGuide_Fish_01 = {
          ContentES = "Una vez que hayas lanzado la línea, espera a que el botón del carrete parpadee, eso significa que un pez ha mordido el anzuelo. Recoge la línea rápidamente antes de que se escape."
        },
        UIGuide_Fish_02 = {
          ContentES = "Durante la recogida, mantén la vista en el indicador a la derecha. Mantén presionado el botón del carrete para aplicar tensión, alinea el indicador con la marca del pez y sostén firme hasta que la captura sea tuya."
        },
        UIGuide_Fish_03 = {
          ContentES = "Atrapar una presa grande puede activar la <H>Oportunidad de Pescar peces más grandes</>. Usa tu captura actual como cebo y lanza de nuevo, podrías conseguir un premio aún más raro."
        },
        UIGuide_Fish_04 = {
          ContentES = "Cuando pescas con un Geniemon con el rasgo \"En paz\", la recogida es automática."
        },
        UIGuide_Fish_05 = {
          ContentES = "Algunas especies solo aparecen en momentos específicos. Puedes cambiar la hora actual desde la interfaz de <H>Ciclo de tiempo</>."
        },
        UIGuide_Fish_SubTitle_1 = {
          ContentES = "Lanzar y recoger"
        },
        UIGuide_Fish_SubTitle_2 = {
          ContentES = "Combate de carrete"
        },
        UIGuide_Fish_SubTitle_3 = {
          ContentES = "Pescar peces más grandes"
        },
        UIGuide_Fish_SubTitle_4 = {
          ContentES = "Pesca con Geniemons"
        },
        UIGuide_Fish_SubTitle_5 = {
          ContentES = "Los peces pican tanto de día como de noche"
        },
        UIGuide_Fish_Title = {
          ContentES = "Hora de una emocionante sesión de pesca."
        },
        UIGuide_Fort_1_PC = {
          ContentES = "Acércate a la torreta 4 y presiona &Interactive& para activarla. La torreta 4 está equipada con <H>Proyectiles de Alta Explosividad</> y <H>Disparos de Alta Cadencia</>."
        },
        UIGuide_Fort_1_Phone = {
          ContentES = "Acércate a la torreta 4 e <H>interactúa</> para activarla. La torreta 4 está equipada con <H>Proyectiles de Alta Explosividad</> y <H>Disparos de Alta Cadencia</>."
        },
        UIGuide_Fort_2 = {
