        UIGuide_RongQi_1 = {
          ContentES = "Los contenedores de la arena guardan reliquias de distinto valor. Al abrirlos, su contenido se valora automáticamente. Luego puedes guardar las reliquias de mayor valor en tu saco de tesoros."
        },
        UIGuide_Rouge_1 = {
          ContentES = "El espacio dentro del Abismo es inestable y cambia constantemente. Luego de completar cada fase, aparecerán nuevas puertas que llevan a distintos tipos de zonas. Elige tu camino y continúa tu exploración."
        },
        UIGuide_Rouge_2_1 = {
          ContentES = "Zona de Abisoide: Centrado en combate. Derrota los Abisoides para ganar recompensas como Brasas."
        },
        UIGuide_Rouge_2_2 = {
          ContentES = "Zona de Eco: Contiene eventos impredecibles conocidos como encuentros."
        },
        UIGuide_Rouge_2_3 = {
          ContentES = "Zona de Descanso: Una zona segura donde puedes intercambiar Brasas por suministros, restaurar PV y recuperar Cordura."
        },
        UIGuide_Run_PC = {
          ContentES = "Mantén &Avoid& para correr."
        },
        UIGuide_Run_Phone = {
          ContentES = "Mantén presionado el botón para correr."
        },
        UIGuide_SIDEWAYSJUMP = {
          ContentES = "Cuando te encuentres cerca de una pared escalable, mantén una dirección y presiona &Jump& <H>repetidamente</> para saltar hacia los lados y realizar saltos consecutivos en la pared."
        },
        UIGuide_Saiqi_1 = {
          ContentES = "Presiona &Skill1& para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche."
        },
        UIGuide_Saiqi_1_Gamepad = {
          ContentES = "Presiona &GamepadUseSkill& + &Attack& para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche."
        },
        UIGuide_Saiqi_1_Phone = {
          ContentES = "Presiona el botón para que Psyche cree 1 [Fantasma] y luego se proyecte hacia adelante. Esta habilidad se puede usar en cualquier momento sin interrumpir la acción actual de Psyche."
        },
        UIGuide_Saiqi_2 = {
          ContentES = "Presiona &Skill2& para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar."
        },
        UIGuide_Saiqi_2_Gamepad = {
          ContentES = "Presiona &GamepadUseSkill& + &Interactive& para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar."
        },
        UIGuide_Saiqi_2_Phone = {
          ContentES = "Presiona el botón para que Psyche entre en estado [Metamorfosis Radiante] y obtenga la habilidad de volar. En estado [Metamorfosis Radiante], Psyche solo puede usar habilidades y disparar. En estado [Metamorfosis Radiante], [Tejido de Crisálida Onírica] se reemplaza por [Fototaxis]: Se lanza hacia adelante y dispara [Polvo Etéreo] que se fija automáticamente en un enemigo aleatorio, causando Daño Anemo al impactar."
        },
        UIGuide_Shadow_1 = {
          ContentES = "Usa el <H>Sello de compañero de combate</> para invocar aliados en batalla. Arrastra los Sellos de compañero de combate a la Mochila táctica para habilitar las invocaciones."
        },
        UIGuide_Shadow_2 = {
          ContentES = "Mantén &OpenBattleWheel& para invocar aliados, que luchará junto a tu personaje actual."
        },
        UIGuide_ShanYe_1 = {
          ContentES = "Utiliza la función Atracción del Nexo Mecánico para hacer girar las aspas, generar una corriente de aire y abrir la puerta mecánica."
        },
        UIGuide_ShenJi_1 = {
          ContentES = "Usa Nexo mecánico: Disipador de corrupción para señalar el punto de impacto en el suelo y guiar el disparo del Cañón celestial."
        },
        UIGuide_ShenJi_2 = {
          ContentES = "El Cañón celestial tiene un tiempo de recarga entre disparos. Inflige muchísimo daño a los enemigos."
        },
        UIGuide_ShengMing_1 = {
          ContentES = "Puedes obtener <H>reputación</> mediante <H>Desafío</> y <H>Contribución</>. La reputación tiene un límite semanal."
        },
        UIGuide_ShengMing_2 = {
          ContentES = "Los Desafíos se dividen en tres niveles de dificultad. Tras aceptar y completar uno, obtendrás Reputación y desbloquearás el siguiente nivel de dificultad. Los Desafíos se actualizan automáticamente cada día."
        },
        UIGuide_ShengMing_3 = {
          ContentES = "Obtén Reputación reuniendo y entregando los objetos requeridos para las Contribuciones. Las Contribuciones se actualizan automáticamente cada semana, o puedes actualizarlas al instante gastando Monedas."
        },
        UIGuide_ShouHu_1 = {
          ContentES = "En la arena aparecerán contenedores especiales sellados que solo pueden abrirse al completar una misión de defensa."
        },
        UIGuide_ShouHu_2 = {
          ContentES = "Interactúa con un contenedor sellado para iniciar la misión. La misión dura alrededor de un minuto. Durante ese tiempo, oleadas de enemigos aparecerán y atacarán los contenedores. Elimínalos antes de que destruyan todos los contenedores o la misión fracasará.\nAntes de que un contenedor sea destruido por completo, mantén presionado F para repararlo. Cuando termine la cuenta regresiva, la misión se completará si queda más de un contenedor en la arena. Todos los contenedores protegidos con éxito podrán abrirse."
        },
        UIGuide_Sojourns_01 = {
          ContentES = "<Highlight>Fragmentos de memoria</> desbloqueados. Selecciona el icono en el Santuario para acceder."
        },
        UIGuide_Sojourns_01_Pad = {
          ContentES = "<Highlight>Fragmentos de memoria</> ahora desbloqueados. Pulsa en el Santuario para acceder."
        },
        UIGuide_Sojourns_02 = {
          ContentES = "Los <Highlight>Fragmentos de memoria</> capturan fragmentos de tiempo y memoria."
        },
        UIGuide_Sojourns_03 = {
          ContentES = "Visita <Highlight>Antología del tiempo</> para ver historias de las diferentes etapas de la vida de un personaje."
        },
        UIGuide_Sojourns_03_Pad = {
          ContentES = "Pulsa para visitar <Highlight>Antología del tiempo</> y explorar historias de distintas etapas de la experiencia de un personaje."
        },
        UIGuide_Sojourns_04 = {
          ContentES = "Cada personaje tiene su propio conjunto de historias."
        },
        UIGuide_Sojourns_04_Pad = {
          ContentES = "Pulsa para explorar la historia única de cada personaje."
        },
        UIGuide_Sojourns_05 = {
          ContentES = "Usa <Highlight>Huella del alma</> para reconstruir estas historias. Algunas entradas tienen requisitos especiales."
        },
        UIGuide_Sojourns_06 = {
          ContentES = "Cumple los requisitos para desbloquear historias y ganar recompensas."
        },
        UIGuide_Sojourns_06_Pad = {
          ContentES = "Las historias se desbloquearán una vez cumplidos los requisitos. Pulsa para reclamar las recompensas asociadas"
        },
        UIGuide_Sojourns_07 = {
          ContentES = "Las historias desbloqueadas pueden revisitar en <Highlight>Instante eterno</>."
        },
        UIGuide_Sp = {
          ContentES = "El recurso principal necesario para usar habilidades en batalla. <H>Se restaura</> con el tiempo."
        },
        UIGuide_SpecialDestructible_1 = {
          ContentES = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico."
        },
        UIGuide_SpecialDestructible_2 = {
          ContentES = "Por ejemplo, la <H>Criolita</> que cubre algunos cofres puede ser destruida con <H>Efecto Adicional: Contundente, Efecto Adicional: Pyro, o habilidades que infligen Daño Pyro</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)"
        },
        UIGuide_SpecialDestructible_3 = {
          ContentES = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\nLas <H>Vid Umbro</> que cubren algunos cofres pueden ser destruidas con <H>Efecto Adicional: Cortante, Efecto Adicional: Lumino, o habilidades que infligen Daño Lumino</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)"
        },
        UIGuide_SpecialDestructible_4 = {
          ContentES = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\nLa <H>Grava</> que cubre algunos cofres puede ser destruida con <H>Efecto Adicional: Contundente</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)"
        },
        UIGuide_SpecialDestructible_5 = {
          ContentES = "Algunos objetos solo pueden ser destruidos por <H>Efectos Adicionales específicos</> o <H>Daño de Habilidades específicos</> que infligen daño específico.\nEl <H>Escudo Lumino</> que cubre algunos cofres puede ser destruido con <H>Efecto Adicional: Perforante, Efecto Adiciona: Umbro, o habilidades que infligen Daño Umbro</>.\n(Los <H>atributos</> del personaje y del arma, y la <H>probabilidad</> de activar efectos adicionales, pueden verse en el Arsenal.)"
        },
        UIGuide_SpecialSideStoryUI1 = {
          ContentES = "Es posible que encuentres algunas Misiones secundarias especiales. Están marcadas con un indicador azul en la lista de misiones."
        },
        UIGuide_SpecialSideStoryUI2 = {
          ContentES = "También pueden aparecer Misiones secundarias especiales durante la exploración. Completarlas puede desbloquear nuevas características o funciones."
        },
        UIGuide_SuYi_GamePad_1 = {
          ContentES = "Pulsa &GamepadUseSkill&+&Attack& para entrar en [Hacia el sol], obtener vuelo a alta velocidad e infligir daño Lumino a los enemigos en la trayectoria. Este estado consume [energía de artificiero] de forma continua y termina cuando la energía llega a 0 o al volver a usar la habilidad."
        },
        UIGuide_SuYi_PC_1 = {
          ContentES = "Pulsa &Skill1& para entrar en [Hacia el sol], obtener vuelo a alta velocidad e infligir daño Lumino a los enemigos en la trayectoria. Este estado consume [energía de artificiero] de forma continua y termina cuando la energía llega a 0 o al volver a usar la habilidad."
        },
        UIGuide_SuYi_PC_2 = {
          ContentES = "Mantén presionado &Jump& para entrar en [Rumbo al cielo] y obtener vuelo vertical. Este estado consume [energía de artificiero] de forma continua y termina cuando [energía de artificiero] llega a 0 o al soltar &Jump&."
        },
        UIGuide_SuYi_Phone_1 = {
          ContentES = "Toca el botón de habilidad para entrar en [Hacia el sol], obtener vuelo a alta velocidad e infligir daño Lumino a los enemigos en la trayectoria. Este estado consume [energía de artificiero] de forma continua y termina cuando la energía llega a 0 o al volver a usar la habilidad."
        },
        UIGuide_SuYi_Phone_2 = {
          ContentES = "Mantén presionado el botón de habilidad para entrar en [Rumbo al cielo] y obtener vuelo vertical. Este estado consume [energía de artificiero] de forma continua y termina cuando [energía de artificiero] llega a 0 o al soltar el botón."
        },
        UIGuide_SwitchMaster_PC = {
          ContentES = "En áreas seguras, <H>mantén pulsado</> &Skill3& para cambiar {性别:al|a la} protagonista para explorar o interactuar."
        },
        UIGuide_SwitchMaster_Phone = {
          ContentES = "En áreas seguras, <H>mantén pulsado</> el botón indicado para cambiar {性别:al|a la} protagonista para explorar o interactuar."
        },
        UIGuide_TaskAcceptance = {
          ContentES = "Al explorar un pueblo, interactuar con algunos residentes locales puede activar Misiones secundarias ocultas."
        },
        UIGuide_TeYao_1 = {
          ContentES = "En esta arena especial, las monedas pueden canjearse por invitaciones con límite semanal. Tras cada extracción, las fichas obtenidas se convierten proporcionalmente en monedas para la liquidación."
        },
        UIGuide_Team_1 = {
          ContentES = "Puedes invitar amigos para formar un equipo y completar un encargo juntos."
        },
        UIGuide_Team_2_PC = {
          ContentES = "La <H>información del equipo</> se muestra en la parte <H>inferior izquierda</> de las interfaces de <H>Amigos</>, <H>Encargos</> y <H>Inicio</>."
        },
        UIGuide_Team_2_Phone = {
          ContentES = "La <H>información del equipo</> se muestra en la parte <H>superior derecha</> de las interfaces de <H>Amigos</>, <H>Encargos</> y <H>Inicio</>."
        },
        UIGuide_Temple_1 = {
          ContentES = "Meditando en ciertos lugares registrados, puedes acceder a las Pruebas de Ave espiritual, desbloqueando una serie de desafíos especiales."
        },
        UIGuide_Temple_2 = {
          ContentES = "Recibirás recompensas de hasta cinco estrellas tras completar con éxito las pruebas por primera vez. Puedes repetirlas para obtener calificaciones más altas y mejores recompensas."
        },
        UIGuide_Temple_3 = {
          ContentES = "Puedes desafiar las Pruebas de Ave espiritual haciendo clic en las ubicaciones registradas en el mapa."
        },
        UIGuide_TianQi_1 = {
          ContentES = "En ciertas fases de la partida comenzará a llover. Durante la lluvia, aparecerán enemigos de élite en ubicaciones fijas. Al derrotarlos, es posible que aparezcan contenedores especiales con reliquias de alto valor.\nLa lluvia también indica que la partida se acelera, así que vigila el tiempo restante y no pierdas el ritmo del combate."
