        UI_Accessory_Custom_Save_Content = {
          ContentES = "¿Deseas guardar los parámetros personalizados del accesorio actual?"
        },
        UI_Accessory_Custom_Scale = {ContentES = "Escala"},
        UI_Accessory_Desc_10001 = {
          ContentES = "Protagonista del famoso cuento infantil del Continente de Atlasia <I>La Extraña Aventura de Joe Joe</>: un pollito llamado Joe Joe que cuenta cómo cada día despierta en un lugar diferente, conoce nuevos amigos y emprende aventuras extraordinarias en busca del sentido de la vida de pollo, mientras descubre las conspiraciones del villano."
        },
        UI_Accessory_Desc_10002 = {
          ContentES = "¡Recuerda, no es comestible!"
        },
        UI_Accessory_Desc_10003 = {
          ContentES = "Vivaz, adorable, alegre, hermoso... todos los adjetivos del mundo que describen la belleza palidecen ante las orejas de gato; ese es el poder irresistible de las orejas de gato."
        },
        UI_Accessory_Desc_10004 = {
          ContentES = "Edición portátil de Cinder, imbuida con la inspiración y pasión desbordante de Lunoherrera, que hace recordar constantemente el ardiente fuego del horno que Cinder mantiene encendido."
        },
        UI_Accessory_Desc_10005 = {
          ContentES = "Símbolo de elegancia, manifestación de la etiqueta o, quizás, una mariposa incapaz de volar."
        },
        UI_Accessory_Desc_10006 = {
          ContentES = "Los dragones han tenido miles de admiradores en todas las épocas; son poderosos, salvajes, pero también distantes y misteriosos porque pocos los han visto. Es precisamente este concepto misterioso el que construye un territorio infinito donde las personas pueden dar rienda suelta a su imaginación."
        },
        UI_Accessory_Desc_10007 = {
          ContentES = "Bajo el cascarón hay más cascarón, bajo el cascarón solo hay cascarón, ¡definitivamente no es una Luno, absolutamente no!"
        },
        UI_Accessory_Desc_10008 = {
          ContentES = "El estado de ánimo de hoy se muestra en la imagen."
        },
        UI_Accessory_Desc_10012 = {
          ContentES = "Llevarlo te hará especialmente hábil para \"perforar\" investigaciones."
        },
        UI_Accessory_Desc_10013 = {
          ContentES = "Máscara conmemorativa de los ancestros Huaxu. Al usarla, parece que puedes ver a decenas de miles de personas con armaduras y máscaras, abriendo el cielo y la tierra, buscando la paz eterna para todas las generaciones."
        },
        UI_Accessory_Desc_10014 = {
          ContentES = "En el pasado, algunos la usaban para comunicarse con las deidades y pedir la bendición de la abundancia. Ahora, las personas veneran la alta torre de Elysium, ansiando la gracia de los milagros."
        },
        UI_Accessory_Desc_10024 = {
          ContentES = "La persona que buscas no está disponible: no está hoy, no estará mañana y nunca estará disponible."
        },
        UI_Accessory_Desc_10026 = {
          ContentES = "La publicidad ya se ha filtrado en todos los aspectos de la vida de las personas."
        },
        UI_Accessory_Desc_10028 = {
          ContentES = "La inspiración fluye sin cesar."
        },
        UI_Accessory_Desc_10029 = {
          ContentES = "Uno de los recuerdos promocionales de \"Cuentos del Lago Glacial\"."
        },
        UI_Accessory_Desc_10030 = {
          ContentES = "En teoría: un adorable paraguas cortaviento y lluvia.\nEn la práctica: un poco más pequeño que en la foto… realmente más pequeño."
        },
        UI_Accessory_Desc_10031 = {
          ContentES = "El fuego fundido no puede quemar las lágrimas devotas ni las plegarias."
        },
        UI_Accessory_Desc_10032 = {
          ContentES = "Alas de mariposa hechas de cinta de raso que llevan pensamientos danzantes mecidos por el viento... ¿en el cabello de quién acabarán posándose?"
        },
        UI_Accessory_Desc_10033 = {
          ContentES = "Cada hacha que cae al lago termina apareciendo en la cabeza de un duende inocente."
        },
        UI_Accessory_Desc_10034 = {
          ContentES = "ZZZZZZZZZZZZZZZZZZ..."
        },
        UI_Accessory_Desc_10035 = {
          ContentES = "Accesorio de gatito"
        },
        UI_Accessory_Desc_10036 = {
          ContentES = "¡Toc toc toc toc… pequeños cascos asustados!"
        },
        UI_Accessory_Desc_10037 = {
          ContentES = "El estado de ánimo de hoy se muestra en la imagen."
        },
        UI_Accessory_Desc_10049 = {
          ContentES = "Corona que refleja la aurora boreal, testigo de los votos cálidos de las personas."
        },
        UI_Accessory_Desc_10050 = {
          ContentES = "El pajarito voló de su nido cálido; esta vez, ¿qué tipo de historia traerá de vuelta?"
        },
        UI_Accessory_Desc_10052 = {
          ContentES = "Algunos habitantes de Huaxu parecen tener sentimientos especiales hacia cierto artrópodo antiguo y resistente, como se puede ver en este accesorio."
        },
        UI_Accessory_Desc_10053 = {
          ContentES = "El sol ardiente ya no puede impedirnos meter todo un verano en nuestros ojos."
        },
        UI_Accessory_Desc_10056 = {
          ContentES = "Lo hecho, hecho está; nada puede deshacerse."
        },
        UI_Accessory_Desc_10057 = {
          ContentES = "Tras escuchar la historia del viejo viajero, algunos rindieron al Phoxorro una devoción casi fanática. Llevar este tocado es una forma de expresar esa fascinación."
        },
        UI_Accessory_Desc_10067 = {
          ContentES = "¡Te deseo prosperidad!"
        },
        UI_Accessory_Desc_10068 = {
          ContentES = "Que se cumpla la ley del Cielo."
        },
        UI_Accessory_Desc_10072 = {
          ContentES = "Viento a tus talones, suerte de tu lado."
        },
        UI_Accessory_Desc_10076 = {
          ContentES = "Plumas esmeralda que abrazan sol y luna; destellos dorados que iluminan el mundo."
        },
        UI_Accessory_Desc_10080 = {
          ContentES = "Una coronación bajo la bendición de las estrellas y la nieve."
