        UI_Skin_Des_3201 = {
          ContentES = "Las cadenas y las espinas marcan el castigo por el pecado y atan el fuego justo que arde en nuestro interior."
        },
        UI_Skin_Des_3202 = {
          ContentES = "Un brillo espléndido perfila curvas que roban el aliento; cada gesto exhala una neblina donde se funden el vino y la noche."
        },
        UI_Skin_Des_3301 = {
          ContentES = "Un casco multiusos forjado a partir de una olla: una armadura resistente para una chica recicladora."
        },
        UI_Skin_Des_4101 = {
          ContentES = "Un azul salpicado de estrellas brilla en su uniforme: una voluntad de proteger y una mirada hacia el futuro."
        },
        UI_Skin_Des_410101 = {
          ContentES = "Sombras derramadas bajo la luna; un medio marcapáginas murmura de dioses y espectros."
        },
        UI_Skin_Des_4102 = {
          ContentES = "La luz del sol se derrama sobre el suntuoso brocado como oro fundido: el amanecer de la revolución se refleja en sus ojos dorados."
