        UI_Skin_Des_410201 = {
          ContentES = "Entre el entrelazarse de las copas y las voces, fluyen enfrentamientos silenciosos."
        },
        UI_Skin_Des_4201 = {
          ContentES = "El trueno del cielo recorre su cuerpo. Cumpliendo el mandato de Dafeng, el pecado no encuentra refugio, ni él tampoco."
        },
        UI_Skin_Des_4202 = {
          ContentES = "Una medalla brilla con una mente genial arriba. Un uniforme late con el corazón de un hombre común abajo."
