        voice_ch_char_Lise_vo_skill02_r02 = {
          ContentES = "La corriente os silenciará."
        },
        voice_ch_char_Lise_vo_skill02_r03 = {
          ContentES = "Es que... ¡Yo elegí seguir viviendo!"
        }
      }
