        voice_ch_char_Suyi_vo_topic_02_5 = {
          ContentES = "Jejeje… Si en algún momento Kezhou se atreve a hablarte con altanería, puedes aprovechar para obligarlo a que te llame {性别:abuelo|abuela}."
